  {View v;init(v,f(transfer,"source_key").string());const auto& tr=f(transfer,"trace").array();for(std::size_t n=0;n<10;++n){auto payload=f(tr[n],"payload");if(n==2)payload.object().at("heard_chord_and_role")="uncertain";if(n==9)payload.object().at("diagnosis")="I was uncertain about the heard context.";apply(v,f(tr[n],"action").string(),payload);}check(f(v.learnerView(),"state").string()=="needs_retry","Uncertain hearing was accepted as yes");check(f(v.learnerView(),"previously_revealed").boolean(),"Required reveal history absent");apply(v,"retry","I will hear the chord and role again.");check(f(v.learnerView(),"previously_revealed").boolean()&&v.learnerView().find("reference_pitch")==nullptr,"Retry erased previous exposure or kept live answer");}
