  {View v;init(v,f(reconstruction,"source_key").string());check(!hasAction(v,"reveal_source"),"Premature reconstruction reveal offered");const auto& tr=f(reconstruction,"trace").array();for(int n=0;n<5;++n)apply(v,f(tr[static_cast<std::size_t>(n)],"action").string(),f(tr[static_cast<std::size_t>(n)],"payload"));check(select(v,"commit_written"),"Written form missing");const auto g=button(v,"advanced-submit").capture();check(!v.prepareForNavigation(),"Writing escaped source-release fence");unchanged(v,[&]{button(v,"advanced-submit").deliver(g);});}
  {View v;init(v,f(fixed,"source_key").string());const auto& tr=f(fixed,"trace").array();for(int n=0;n<3;++n)apply(v,f(tr[static_cast<std::size_t>(n)],"action").string(),f(tr[static_cast<std::size_t>(n)],"payload"));check(select(v,"name_role"),"Role naming missing");fill(v,v.selectedSchema(),O{{"role",nullptr},{"notes","I cannot identify this role."}});deliver(v,"advanced-submit");check(f(v.learnerView(),"state").string()=="ready_play","Unknown role was converted into an answer");for(std::size_t n=4;n<=6;++n){auto payload=f(tr[n],"payload");if(n==6)payload.object().at("diagnosis")="I could not identify the fixed top role.";apply(v,f(tr[n],"action").string(),payload);}check(f(v.learnerView(),"state").string()=="needs_retry","Unknown fixed role completed without diagnosis");apply(v,"diagnose","I will identify the role before retrying.");}
  {View v;init(v,f(debt,"source_key").string());for(const auto& s:f(debt,"trace").array()){if(s.find("refuse"))continue;apply(v,f(s,"action").string(),f(s,"payload"));if(f(v.workflow()->snapshot(),"reduction_required").boolean()){const auto before=v.workflow()->snapshot();check(!v.prepareForNavigation(),"Debt escaped active release");check(f(v.workflow()->snapshot(),"reduction_required").boolean(),"Navigation cleared mandatory reduction");check(select(v,"release"),"Debt navigation release unavailable");fill(v,v.selectedSchema(),O{{"learner_released",true}});deliver(v,"advanced-submit");check(v.prepareForNavigation(),"Debt release did not unlock navigation");v.resumeAfterNavigation();check(f(v.workflow()->snapshot(),"reduction_required")==f(before,"reduction_required"),"Settings detour forgave reduction");check(historyCount(v)>0,"Debt history lost");break;}}}
  {View v;init(v,f(transfer,"source_key").string());const auto& tr=f(transfer,"trace").array();for(int n=0;n<4;++n)apply(v,f(tr[static_cast<std::size_t>(n)],"action").string(),f(tr[static_cast<std::size_t>(n)],"payload"));check(select(v,"choose_arrangements"),"Arrangement form missing");auto& count=control<juce::ComboBox>(v,"advanced-count-input/string_set_1/strings");auto old=count.onChange;check(select(v,"cancel"),"Cancel form missing");unchanged(v,[&]{old();});}
  {View v;init(v,f(transfer,"source_key").string());const auto& tr=f(transfer,"trace").array();for(std::size_t n=0;n<5;++n)apply(v,f(tr[n],"action").string(),f(tr[n],"payload"));const auto cached=v.learnerTextLayoutCount();for(std::size_t n=5;n<8;++n)apply(v,f(tr[n],"action").string(),f(tr[n],"payload"));check(v.learnerTextLayoutCount()==cached,"Silent setup/attack/release re-laid stable source text");apply(v,f(tr[8],"action").string(),f(tr[8],"payload"));check(v.learnerTextLayoutCount()==cached+1,"Permitted reveal did not refresh source text exactly once");check(select(v,"report"),"Cached report action missing");const auto learnerBefore=v.learnerTextLayoutCount(),historyBefore=v.historyTextLayoutCount();unchanged(v,[&]{deliver(v,"advanced-submit");});check(v.learnerTextLayoutCount()==learnerBefore&&v.historyTextLayoutCount()==historyBefore,"Refused blank input re-laid unchanged source/history");}
